    loads = [
        delivered("A", 0),
        delivered("B", 45, code="WX"),
        delivered("C", 45, code="CARR"),
        Delivery("D", WINDOW_END, status="cancelled"),
    ]
    assert scorecard_counts(loads) == {"on_time": 1, "late": 1, "excused": 1, "skipped": 1}


